<script>
import TitleLine from './modules/TitleLine'
import { buyrecordNew } from '@/api/game'
export default {
  components: {
    TitleLine
  },
  props: {
    // currentValue: {
    //   type: Number,
    //   default: 0
    // }
  },
  data() {
    return {
      themeColor: process.env.VUE_APP_BASE_THEME,
      title: this.$t('hxhash.hx08'), // '充提记录',
      gameMenuType: this.$t('hxhash.hx117'),
      currentDateLabel: this.$t('wdsr.wdsr44'),
      showPickType: false,
      showTimeType: false,
      currentValue: 1,
      totalData: {},
      recordList: [
        // { pic: transIcon1, title: '第三方 > 主账号', time: '2023-09-09 10:21:47', mons: '10.86', status: '转账成功' },
        // { pic: transIcon1, title: '第三方 > 主账号', time: '2023-09-09 10:21:47', mons: '10.86', status: '转账成功' }
      ],
      // value 待调试
      gameMenuList: [{ name: this.$t('hxhash.hx117'), value: 'all', choosed: true }, { name: this.$t('home.sy10'), value: '1', choosed: false }, { name: this.$t('home.sy11'), value: '2', choosed: false }, { name: this.$t('home.sy12'), value: '3', choosed: false }, { name: this.$t('home.sy13'), value: '4', choosed: false }, { name: this.$t('home.sy132'), value: '0', choosed: false }],//, { name: this.$t('home.sy133'), value: '0', choosed: false }
      dateList: [{ name: this.$t('wdsr.wdsr44'), value: '1', choosed: true }, { name: this.$t('wdsr.wdsr45'), value: '2', choosed: false }],
      mons: '',
      loading: false,
      finished: false,
      refreshing: false,
      pageNum: 1,
      pageSize: 10
    }
  },
  created() {
    // this.getData()
  },
  methods: {
    toDetail(item) {
      localStorage.setItem('tzDetail', JSON.stringify(item))
      // this.$bus.$emit('rechargeDetail', item)
      this.$router.push({
        path: '/orderRecordDetail'
      })
    },
    closePop() {
      this.showPickType = false
      // 将勾选的name存入gameMenuType
      this.gameMenuType = this.gameMenuList.find(i => i.choosed).name
      this.onRefresh()
    },
    closePop1() {
      this.showTimeType = false
      // 将勾选的name存入currentData
      this.currentDateLabel = this.dateList.find(i => i.choosed).name
    },
    onChooseType(item) {
      this.gameMenuList.forEach(i => {
        i.choosed = false
      })
      item.choosed = true
      this.gameMenuType = item.name
      this.showPickType = false
      this.onRefresh()
    },
    onChooseTime(item) {
      this.dateList.forEach(i => {
        i.choosed = false
      })
      item.choosed = true
      this.currentDateLabel = item.name
      this.currentValue = item.value
      this.showTimeType = false
      this.onRefresh()
    },
    open(url) {
      window.open(url)
    },
    async onLoad() {
      const type = this.gameMenuList.find(i => i.choosed).value
      buyrecordNew({ type: this.currentValue, gametype: type, pages: this.pageNum }).then(res => {
        this.totalData = res.totalData
        if (this.refreshing) {
          this.recordList = []
          this.refreshing = false
        }
        this.recordList = this.recordList.concat(res.datalist)
      //   this.recordList =[
      //   { pic: '', title: '第三方 > 主账号', time: '2023-09-09 10:21:47', mons: '10.86', status: '转账成功' },
      //   { pic: '', title: '第三方 > 主账号', time: '2023-09-09 10:21:47', mons: '10.86', status: '转账成功' }
      // ,{ pic: '', title: '第三方 > 主账号', time: '2023-09-09 10:21:47', mons: '10.86', status: '转账成功' },
      //   { pic: '', title: '第三方 > 主账号', time: '2023-09-09 10:21:47', mons: '10.86', status: '转账成功' }
      // ,{ pic: '', title: '第三方 > 主账号', time: '2023-09-09 10:21:47', mons: '10.86', status: '转账成功' },
      //   { pic:'' , title: '第三方 > 主账号', time: '2023-09-09 10:21:47', mons: '10.86', status: '转账成功' }
      // ,{ pic: '', title: '第三方 > 主账号', time: '2023-09-09 10:21:47', mons: '10.86', status: '转账成功' },
      //   { pic: '', title: '第三方 > 主账号', time: '2023-09-09 10:21:47', mons: '10.86', status: '转账成功' }
      // ,{ pic: '', title: '第三方 > 主账号', time: '2023-09-09 10:21:47', mons: '10.86', status: '转账成功' },
      //   { pic:'' , title: '第三方 > 主账号', time: '2023-09-09 10:21:47', mons: '10.86', status: '转账成功' }
      // ,{ pic: '', title: '第三方 > 主账号', time: '2023-09-09 10:21:47', mons: '10.86', status: '转账成功' },
      //   { pic: '', title: '第三方 > 主账号', time: '2023-09-09 10:21:47', mons: '10.86', status: '转账成功' }
      // ,{ pic: '', title: '第三方 > 主账号', time: '2023-09-09 10:21:47', mons: '10.86', status: '转账成功' },
      //   { pic: '', title: '第三方 > 主账号', time: '2023-09-09 10:21:47', mons: '10.86', status: '转账成功' }
      // ,{ pic: '', title: '第三方 > 主账号', time: '2023-09-09 10:21:47', mons: '10.86', status: '转账成功' },
      //   { pic: '', title: '第三方 > 主账号', time: '2023-09-09 10:21:47', mons: '10.86', status: '转账成功' }
      // ,{ pic: '', title: '第三方 > 主账号', time: '2023-09-09 10:21:47', mons: '10.86', status: '转账成功' },
      //   { pic:'' , title: '第三方 > 主账号', time: '2023-09-09 10:21:47', mons: '10.86', status: '转账成功' }
      //   ,{ pic: '', title: '第三方 > 主账号', time: '2023-09-09 10:21:47', mons: '10.86', status: '转账成功' },
      //   { pic: '', title: '第三方 > 主账号', time: '2023-09-09 10:21:47', mons: '10.86', status: '转账成功' }
      // ]
        this.loading = false
        this.pageNum++
        if (this.recordList.length >= Number(res.allnums)) {
          this.finished = true
        }
      })
    },
    onRefresh() {
      // 清空列表数据
      this.finished = false
      this.pageNum = 1
      this.refreshing = true
      // 重新加载数据
      // 将 loading 设置为 true，表示处于加载状态
      this.loading = true
      this.onLoad()
    }
  }

}
