import request from '@/utils/request'
import i18n from '@/i18n/i18n'
function handleData(val) {
  return val.slice(0, 4) + '****' + val.slice(val.length - 8, val.length)
}
// 综合明细
export function getIssueDetail(query) {
  return request({
    url: '/' + query.gametype + '/getIssueDetail',
    method: 'get',
    params: query
  })
}
// 单双信息
export function getGameInfo(query) {
  const params = { gametype: query.gametype === 'gameSP' ? '11' : '1' }
  return request({
    url: '/' + query.gametype + '/getGameInfo',
    method: 'get',
    params
  })
}
// 开奖信息
export function getOpenInfo(data) {
  return request({
    url: '/' + data.gametype + '/getOpenInfo',
    method: 'get',
    params: data
  }).then(res => {
    res.blockhashShow = handleData(res.blockhash)
    return res
  })
}
// 一分开奖信息
export function getBloackWin(data) {
  return request({
    url: '/' + data.gametype + '/getBloackWin',
    method: 'get',
    params: data
  }).then(res => {
    // res.blockhashShow = handleData(res.blockhash)
    return res
  })
}
// 下单保存
export function save(data) {
  return request({
    url: '/' + data.gametype + '/save',
    method: 'get',
    params: data
  })
}
// 趋势图 总
export function getTrend(data) {
  if (data.index) {
    return request({
      url: '/' + data.gametype + '/getTrend' + data.index,
      method: 'get',
      params: data
    })
  } else {
    return request({
      url: '/' + data.gametype + '/getTrend',
      method: 'get',
      params: data
    })
  }
}
// 投注记录 总
export function buyrecord(data) {
  return request({
    url: '/' + data.type + '/buyrecord',
    method: 'get',
    params: data
  }).then(res => {
    res.totalData = [{ label: i18n.t('tzjl.tzjl14'), value: res.allnums }, { label: i18n.t('tzjl.tzjl15'), value: res.allbuys }, { label: i18n.t('tzjl.tzjl16'), value: res.winmons }]
    res.recordList = res.datalist.map(item => {
      item.blockhashShow = handleData(item.blockhash)
      item.blockurlShow = item.blockurl ? handleData(item.blockurl) : ''
      if (item.gametypename.includes('骰子')) {
        return [{
          label: i18n.t('tzjl.tzjl20'), value: item.buycode }, {
          label: i18n.t('tzjl.tzjl21'), value: item.gametypename }, {
          label: i18n.t('tzjl.tzjl22'), value: item.content }, {
          label: '开奖号码', value: item.opennum }, {
          label: i18n.t('tzjl.tzjl23'), value: item.wintypename }, {
          label: i18n.t('tzjl.tzjl24'), value: item.bmons }, {
          label: i18n.t('tzjl.tzjl25'), value: item.pmons }, {
          // label: '交易哈希', value: item.buycode }, {
          label: i18n.t('tzjl.tzjl26'), value: item.block, showValue: item.block }, {
          label: i18n.t('tzjl.tzjl27'), value: item.blockurl, showValue: item.blockurlShow }, {
          label: i18n.t('tzjl.tzjl28'), value: item.blockhash, showValue: item.blockhashShow }, {
          label: i18n.t('tzjl.tzjl29'), value: item.btime }
        ]
      } else {
        return [{
          label: i18n.t('tzjl.tzjl20'), value: item.buycode }, {
          label: i18n.t('tzjl.tzjl21'), value: item.gametypename }, {
          label: i18n.t('tzjl.tzjl22'), value: item.content }, {
          label: i18n.t('tzjl.tzjl23'), value: item.wintypename }, {
          label: i18n.t('tzjl.tzjl24'), value: item.bmons }, {
          label: i18n.t('tzjl.tzjl25'), value: item.pmons }, {
          // label: '交易哈希', value: item.buycode }, {
          label: i18n.t('tzjl.tzjl26'), value: item.block, showValue: item.block }, {
          label: i18n.t('tzjl.tzjl27'), value: item.blockurl, showValue: item.blockurlShow }, {
          label: i18n.t('tzjl.tzjl28'), value: item.blockhash, showValue: item.blockhashShow }, {
          label: i18n.t('tzjl.tzjl29'), value: item.btime }
        ]
      }
    })
    return res
  })
}
export function buyrecordAll(data) {
  return request({
    url: '/pay/buyrecord',
    method: 'get',
    params: data
  }).then(res => {
    res.totalData = [{ label: i18n.t('tzjl.tzjl14'), value: res.allnums }, { label: i18n.t('tzjl.tzjl15'), value: res.allbuys }, { label: i18n.t('tzjl.tzjl16'), value: res.winmons }]
    res.recordList = res.datalist.map(item => {
      if (item.blockhash) {
        item.blockhashShow = handleData(item.blockhash)
        item.blockurlShow = item.blockurl ? handleData(item.blockurl) : ''
        if (item.gametypename.includes('骰子')) {
          return [{
            label: i18n.t('tzjl.tzjl20'), value: item.buycode }, {
            label: i18n.t('tzjl.tzjl21'), value: item.gametypename }, {
            label: i18n.t('tzjl.tzjl22'), value: item.content }, {
            label: '开奖号码', value: item.opennum }, {
            label: i18n.t('tzjl.tzjl23'), value: item.wintypename }, {
            label: i18n.t('tzjl.tzjl24'), value: item.bmons }, {
            label: i18n.t('tzjl.tzjl25'), value: item.pmons }, {
            label: i18n.t('tzjl.tzjl26'), value: item.block }, {
            label: i18n.t('tzjl.tzjl27'), value: item.blockurl, showValue: item.blockurlShow }, {
            label: i18n.t('tzjl.tzjl28'), value: item.blockhash, showValue: item.blockhash }, {
            label: i18n.t('tzjl.tzjl29'), value: item.btime }
          ]
        } else {
          return [{
            label: i18n.t('tzjl.tzjl20'), value: item.buycode }, {
            label: i18n.t('tzjl.tzjl21'), value: item.gametypename }, {
            label: i18n.t('tzjl.tzjl22'), value: item.content }, {
            label: i18n.t('tzjl.tzjl23'), value: item.wintypename }, {
            label: i18n.t('tzjl.tzjl24'), value: item.bmons }, {
            label: i18n.t('tzjl.tzjl25'), value: item.pmons }, {
            label: i18n.t('tzjl.tzjl26'), value: item.block }, {
            label: i18n.t('tzjl.tzjl27'), value: item.blockurl, showValue: item.blockurlShow }, {
            label: i18n.t('tzjl.tzjl28'), value: item.blockhash, showValue: item.blockhashShow }, {
            label: i18n.t('tzjl.tzjl29'), value: item.btime }
          ]
        }
      } else if (item.gametypename.includes('加拿大')) {
        return [{
          label: i18n.t('tzjl.tzjl20'), value: item.buycode }, {
          label: i18n.t('tzjl.tzjl21'), value: item.gametypename }, {
          label: i18n.t('tzjl.tzjl22'), value: item.content }, {
          label: i18n.t('tzjl.tzjl23'), value: item.wintypename }, {
          label: i18n.t('tzjl.tzjl24'), value: item.bmons }, {
          label: i18n.t('tzjl.tzjl25'), value: item.pmons }, {
          label: '开奖期号', value: item.block }, {
          label: '开奖号', value: item.open1 + ',' + item.open2 + ',' + item.open3 + ',' + item.opensum }, {
          label: i18n.t('tzjl.tzjl29'), value: item.btime }
        ]
      } else {
        return [{
          label: i18n.t('tzjl.tzjl20'), value: item.buycode }, {
          label: i18n.t('tzjl.tzjl21'), value: item.gametypename }, {
          label: i18n.t('tzjl.tzjl36'), value: item.btime }, {
          label: i18n.t('tzjl.tzjl37'), value: item.bmons }, {
          label: i18n.t('tzjl.tzjl38'), value: item.yxmons }, {
          label: i18n.t('tzjl.tzjl39'), value: item.winmons }, {
          label: i18n.t('tzjl.tzjl40'), value: item.wintypename }
        ]
      }
    })
    return res
  })
}
