// 加拿大投注记录
export function canadaBuyRecord(data) {
  return request({
    url: '/gamePc28a/getBuyList',
    method: 'get',
    params: data
  }).then(res => {
    res.recordList = res.datalist.map(item => {
      return [{
        label: '注单编号', value: item.buycode }, {
        label: '参与游戏', value: item.gametypename }, {
        label: '下注区域', value: item.content }, {
        label: '', value: item.opennum }, {
        label: '中奖情况', value: item.wintypename }, {
        label: '下注金额', value: item.bmons }, {
        label: '返奖金额', value: item.pmons }, {
        label: '开奖期号', value: item.issue }, {
        label: '开奖号', value1: item.open1, value2: item.open2, value3: item.open3, valueSum: item.openSum }, {
        label: '注单时间', value: item.btime }
      ]
    })
    return res
  })
}
