// 已开期号查询
export function searchKey(data) {
  return request({
    url: '/issuekey/list',
    method: 'get',
    params: data
  }).then(res => {
    res.recordList = res.datalist.map(item => {
      item.blockkeyShow = handleData(item.blockkey)
      item.blockurlShow = handleData(item.blockurl)
      return [{
        label: i18n.t('hxhash.hx47'), value: item.blocktime, showValue: item.blocktime }, {
        label: i18n.t('hxhash.hx34'), value: item.block, showValue: item.block }, {
        label: i18n.t('hxhash.hx49'), value: item.blockurl, showValue: item.blockurlShow }, {
        label: i18n.t('hxhash.hx36'), value: item.blockkey, showValue: item.blockkeyShow }
      ]
    })
    return res
  })
}

